// Zweck: HTTP-Body validieren und parametrisiertes SQL für den SQLite-Node vorbereiten.
//
// OPTIMIERUNG gegenüber Vorgänger:
//   1. readPayloadObject() stammt aus den globalen flowHelpers (kein Inline-Duplikat).
//   2. SQL wird als Prepared Statement mit msg.params gebaut statt per String-Verkettung.
//      Das ist sicherer (kein SQL-Injection-Risiko durch manuelles Escaping)
//      und lesbarer (SQL-Template klar sichtbar, Werte separat).
//
// Eingabe:  msg.payload – JSON-Body mit device_id und display_name
// Ausgaben:
//   Output 1 – msg mit parametrisiertem SQL → weiter zum SQLite-Node
//   Output 2 – HTTP-Fehlerantwort (400) bei Validierungsfehler

const flowHelpers = global.get("flowHelpers");
if (!flowHelpers) {
    msg.statusCode = 500;
    msg.payload    = { error: "flow_helpers_unavailable", message: "Boot-Flow prüfen" };
    return [null, msg];
}

// Payload sicher als Objekt lesen (unterstützt JSON-String, Buffer, fertiges Objekt).
const payload = flowHelpers.readPayloadObject(msg.payload);

// device_id ist Pflichtfeld.
const deviceId = typeof payload.device_id === "string" ? payload.device_id.trim() : "";
if (!deviceId) {
    msg.statusCode = 400;
    msg.payload    = { error: "device_id_required", message: "device_id ist ein Pflichtfeld" };
    return [null, msg];
}

// display_name akzeptiert beide Feldnamen aus Kompatibilitätsgründen.
const rawName = typeof payload.display_name === "string"
    ? payload.display_name
    : typeof payload.device_name === "string"
        ? payload.device_name
        : "";
const normalizedName = rawName.trim();

// Länge begrenzen (DB-Feld ist VARCHAR(80)).
if (normalizedName.length > 80) {
    msg.statusCode = 400;
    msg.payload    = { error: "display_name_too_long", message: "display_name darf maximal 80 Zeichen haben" };
    return [null, msg];
}

const updatedAt = new Date().toISOString();

// Merker für den Response-Builder (device_id + gesetzter Name).
msg.dashboardDisplayNameUpdate = {
    device_id:    deviceId,
    display_name: normalizedName || null,
    updated_at:   updatedAt
};

// ── Parametrisiertes Prepared Statement ─────────────────────────────────────
// SQLite-Node.sql = SQL-Template mit Platzhaltern (?)
// msg.params     = Werte-Array in der Reihenfolge der Platzhalter
//
// NULL bei leerem Namen: SQLite RETURNING gibt den gespeicherten Wert zurück,
// sodass das Frontend immer den aktuellen Stand erhält.
msg.params = [
    normalizedName || null,  // NULL setzt den Namen auf Standardwert zurück
    updatedAt,
    deviceId
];

return [msg, null];

// Zweck: SQLite-Ergebnis in eine strukturierte HTTP-Antwort umwandeln.
// Eingabe:  msg.payload          – Array mit RETURNING-Zeile(n) aus dem SQLite-Node
//           msg.dashboardDisplayNameUpdate – Merker aus dem Validierungs-Node
// Ausgabe:  msg.payload mit { device_id, display_name, updated_at } oder 404-Fehler

const update = msg.dashboardDisplayNameUpdate || {};
const rows   = Array.isArray(msg.payload) ? msg.payload : [];
const row    = rows.length > 0 ? rows[0] : null;

// Wenn kein RETURNING-Ergebnis → Gerät existiert nicht in der DB.
if (!row) {
    msg.statusCode = 404;
    msg.payload    = {
        error:     "device_not_found",
        message:   "Gerät nicht in der Datenbank gefunden",
        device_id: update.device_id || null
    };
    return msg;
}

msg.statusCode = 200;
msg.payload    = {
    device_id:    row.device_id    || update.device_id    || null,
    display_name: row.dashboard_display_name              || null,
    updated_at:   row.updated_at   || update.updated_at   || new Date().toISOString()
};
return msg;
